33	// Also prevent duck typing.
34	export const LABEL_LAYOUT_INFO_KIND_RAW = 1 as const;
35	export const LABEL_LAYOUT_INFO_KIND_COMPUTED = 2 as const;
36	
37	// PENDING: a LabelLayoutInfoRaw with `defaultAttr.ignore: false` will become a NullUndefined,
38	//  rather than a LabelLayoutInfoComputed.
39	export type LabelLayoutInfoAll = LabelLayoutInfoRaw | LabelLayoutInfoComputed | NullUndefined;
40	
41	interface LabelLayoutInfoBase {
42	    label: ZRText
43	    labelLine?: Polyline | NullUndefined
44	    layoutOption?: LabelLayoutOption | NullUndefined
45	    priority: number
46	    // Save the original value that may be modified in overlap resolving.
47	    defaultAttr: {
48	        ignore?: boolean
49	        labelGuideIgnore?: boolean
50	    }
51	    ignoreMargin?: boolean; // For backward compatibility.
52	
53	    // In grid (cartesian) estimation process (for `grid.containLabel` and related overflow resolving handlings),
54	    // the `gridRect` is shrunk gradually according to the last union boundingRect of the axis labels and names.
55	    // But the `ignore` stretegy (such as in `hideOverlap` and `fixMinMaxLabelShow`) affects this process
56	    // significantly - the outermost labels might be determined `ignore:true` in a big `gridRect`, but be determined
57	    // `ignore:false` in a shrunk `gridRect`. (e.g., if the third label touches the outermost label in a shrunk
58	    // `gridRect`.) That probably causes the result overflowing unexpectedly. Therefore, `suggestIgnore` is
59	    // introduced to ensure the `ignore` consistent during that estimation process.
60	    suggestIgnore?: boolean;
61	}
62	
63	export interface LabelLayoutInfoRaw extends LabelLayoutInfoBase {
64	    kind: typeof LABEL_LAYOUT_INFO_KIND_RAW
65	    // Should no other properties - ensure to be a subset of LabelLayoutInfoComputed.
66	}
67	
68	export interface LabelLayoutInfoComputed extends LabelLayoutInfoBase, LabelIntersectionCheckInfo {
69	    kind: typeof LABEL_LAYOUT_INFO_KIND_COMPUTED
70	    // The original props in `LabelLayoutInfoBase` are preserved.
71	
72	    // ------ Computed properites ------
73	    // All of the members in `LabelIntersectionCheckInfo`.
74	}
75	
76	export interface LabelIntersectionCheckInfo {
77	    // Global rect from `localRect`
78	    rect: BoundingRect
79	    // Weither the localRect aligns to screen-pixel x or y axis.
80	    axisAligned: boolean
81	    // Considering performance, obb is not created until it is really needed.
82	    // Use `ensureOBB(labelLayoutInfo)` to create and cache obb before using it,
83	    // created by `localRect`&`transform`.
84	    obb: OrientedBoundingRect | NullUndefined
85	    // localRect of the label.
86	    // [CAUTION] do not modify it, since it may be the internal data structure of the el.
87	    localRect: BoundingRect
88	    // transform of `label`. If `label` has no `transform`, this prop is `NullUndefined`.
89	    // [CAUTION] do not modify it, since it may be the internal data structure of the el.
90	    transform: number[] | NullUndefined
91	}
92	
93	export function createLabelLayoutList(
94	    rawList: LabelLayoutInfoRaw[]
95	): LabelLayoutInfoComputed[] {
96	    const resultList: LabelLayoutInfoComputed[] = [];
97	    each(rawList, raw => {
98	        // PENDING: necessary?
99	        raw = extend({}, raw);
100	        const layoutInfo = prepareLabelLayoutInfo(raw);
101	        if (layoutInfo) {
102	            resultList.push(layoutInfo);
103	        }
104	    });
105	    return resultList;
106	}
107	
108	/**
109	 * If `defaultAttr.ignore: true`, return `NullUndefined`.
110	 *  (the caller is reponsible for ensuring the label is always `ignore: true`.)
111	 * Otherwise the `layoutInfo` will be modified and returned.
112	 * `label.ignore` is not necessarily falsy, since it might be modified by some overlap resolving handling.
113	 *
114	 * The result can also be the input of this method.
115	 *
116	 * @see ensureLabelLayoutInfoComputed
117	 */
118	function prepareLabelLayoutInfo(
119	    layoutInfo: LabelLayoutInfoAll
120	): LabelLayoutInfoComputed | NullUndefined {
121	
122	    if (!layoutInfo || layoutInfo.defaultAttr.ignore) {
123	        return;
124	    }
125	
126	    const label = layoutInfo.label;
127	    const ignoreMargin = layoutInfo.ignoreMargin;
128	
129	    const transform = label.getComputedTransform();
130	    // NOTE: Get bounding rect after getComputedTransform, or label may not been updated by the host el.
131	    let localRect = label.getBoundingRect();
132	    const axisAligned = isBoundingRectAxisAligned(transform);
133	
134	    if (!ignoreMargin) {
135	        localRect = applyTextMarginToLocalRect(label, localRect);
136	    }
137	
138	    const globalRect = localRect.clone();
139	    globalRect.applyTransform(transform);
140	
141	    if (!ignoreMargin && (label.style as LabelExtendedTextStyle).__marginType === LabelMarginType.minMargin) {
142	        // `minMargin` only support number value.
143	        const halfMinMargin = ((label.style.margin as number) || 0) / 2;
144	        expandOrShrinkRect(globalRect, halfMinMargin, false, false);
145	    }
146	
147	    const computed = layoutInfo as LabelLayoutInfoComputed;
148	    computed.kind = LABEL_LAYOUT_INFO_KIND_COMPUTED,
149	    // --- computed properties ---
150	    computed.rect = globalRect;
151	    computed.localRect = localRect;
152	    computed.obb = null, // will be created by `ensureOBB` when using.
153	    computed.axisAligned = axisAligned;
154	    computed.transform = transform;
155	
156	    return computed;
157	}
