248	function shiftLayout(
249	    list: Pick<LabelLayoutInfoComputed, 'rect' | 'label'>[],
250	    xyDim: 'x' | 'y',
251	    sizeDim: 'width' | 'height',
252	    minBound: number,
253	    maxBound: number,
254	    balanceShift: boolean
255	) {
256	    const len = list.length;
257	
258	    if (len < 2) {
259	        return;
260	    }
261	
262	    list.sort(function (a, b) {
263	        return a.rect[xyDim] - b.rect[xyDim];
264	    });
265	
266	    let lastPos = 0;
267	    let delta;
268	    let adjusted = false;
269	
270	    const shifts = [];
271	    let totalShifts = 0;
272	    for (let i = 0; i < len; i++) {
273	        const item = list[i];
274	        const rect = item.rect;
275	        delta = rect[xyDim] - lastPos;
276	        if (delta < 0) {
277	            // shiftForward(i, len, -delta);
278	            rect[xyDim] -= delta;
279	            item.label[xyDim] -= delta;
280	            adjusted = true;
281	        }
282	        const shift = Math.max(-delta, 0);
283	        shifts.push(shift);
284	        totalShifts += shift;
285	
286	        lastPos = rect[xyDim] + rect[sizeDim];
287	    }
288	    if (totalShifts > 0 && balanceShift) {
289	        // Shift back to make the distribution more equally.
290	        shiftList(-totalShifts / len, 0, len);
291	    }
292	
293	    // TODO bleedMargin?
294	    const first = list[0];
295	    const last = list[len - 1];
296	    let minGap: number;
297	    let maxGap: number;
298	    updateMinMaxGap();
299	
300	    // If ends exceed two bounds, squeeze at most 80%, then take the gap of two bounds.
301	    minGap < 0 && squeezeGaps(-minGap, 0.8);
302	    maxGap < 0 && squeezeGaps(maxGap, 0.8);
303	    updateMinMaxGap();
304	    takeBoundsGap(minGap, maxGap, 1);
305	    takeBoundsGap(maxGap, minGap, -1);
306	
307	    // Handle bailout when there is not enough space.
308	    updateMinMaxGap();
309	
310	    if (minGap < 0) {
311	        squeezeWhenBailout(-minGap);
312	    }
313	    if (maxGap < 0) {
314	        squeezeWhenBailout(maxGap);
315	    }
316	
317	    function updateMinMaxGap() {
318	        minGap = first.rect[xyDim] - minBound;
319	        maxGap = maxBound - last.rect[xyDim] - last.rect[sizeDim];
320	    }
321	
322	    function takeBoundsGap(gapThisBound: number, gapOtherBound: number, moveDir: 1 | -1) {
323	        if (gapThisBound < 0) {
324	            // Move from other gap if can.
325	            const moveFromMaxGap = Math.min(gapOtherBound, -gapThisBound);
326	            if (moveFromMaxGap > 0) {
327	                shiftList(moveFromMaxGap * moveDir, 0, len);
328	                const remained = moveFromMaxGap + gapThisBound;
329	                if (remained < 0) {
330	                    squeezeGaps(-remained * moveDir, 1);
331	                }
332	            }
333	            else {
334	                squeezeGaps(-gapThisBound * moveDir, 1);
335	            }
336	        }
337	    }
338	
339	    function shiftList(delta: number, start: number, end: number) {
340	        if (delta !== 0) {
341	            adjusted = true;
342	        }
343	        for (let i = start; i < end; i++) {
344	            const item = list[i];
345	            const rect = item.rect;
346	            rect[xyDim] += delta;
347	            item.label[xyDim] += delta;
348	        }
349	    }
350	
351	    // Squeeze gaps if the labels exceed margin.
352	    function squeezeGaps(delta: number, maxSqeezePercent: number) {
353	        const gaps: number[] = [];
354	        let totalGaps = 0;
355	        for (let i = 1; i < len; i++) {
356	            const prevItemRect = list[i - 1].rect;
357	            const gap = Math.max(list[i].rect[xyDim] - prevItemRect[xyDim] - prevItemRect[sizeDim], 0);
358	            gaps.push(gap);
359	            totalGaps += gap;
360	        }
361	        if (!totalGaps) {
362	            return;
363	        }
364	
365	        const squeezePercent = Math.min(Math.abs(delta) / totalGaps, maxSqeezePercent);
366	
367	        if (delta > 0) {
368	            for (let i = 0; i < len - 1; i++) {
369	                // Distribute the shift delta to all gaps.
370	                const movement = gaps[i] * squeezePercent;
371	                // Forward
372	                shiftList(movement, 0, i + 1);
373	            }
374	        }
375	        else {
376	            // Backward
377	            for (let i = len - 1; i > 0; i--) {
378	                // Distribute the shift delta to all gaps.
379	                const movement = gaps[i - 1] * squeezePercent;
380	                shiftList(-movement, i, len);
381	            }
382	        }
383	    }
384	
385	    /**
386	     * Squeeze to allow overlap if there is no more space available.
387	     * Let other overlapping strategy like hideOverlap do the job instead of keep exceeding the bounds.
388	     */
389	    function squeezeWhenBailout(delta: number) {
390	        const dir = delta < 0 ? -1 : 1;
391	        delta = Math.abs(delta);
392	        const moveForEachLabel = Math.ceil(delta / (len - 1));
393	
394	        for (let i = 0; i < len - 1; i++) {
395	            if (dir > 0) {
396	                // Forward
397	                shiftList(moveForEachLabel, 0, i + 1);
398	            }
399	            else {
400	                // Backward
401	                shiftList(-moveForEachLabel, len - i - 1, len);
402	            }
403	
404	            delta -= moveForEachLabel;
405	
406	            if (delta <= 0) {
407	                return;
408	            }
409	        }
410	    }
411	
412	    return adjusted;
413	}
